WITH f AS (SELECT to_regprocedure('public.shipment_outbound_delivery(jsonb,uuid,uuid,uuid,text,text,text,text,text,date,uuid)') AS wrapper, to_regprocedure('public.shipment_outbound_delivery_core_20260722(jsonb,uuid,uuid,uuid,text,text,text,text,text,date,uuid)') AS core), checks AS (SELECT 'missing_batch_stock_check' AS issue FROM f WHERE wrapper IS NULL OR position('day_stock AS MATERIALIZED' IN pg_get_functiondef(wrapper))=0 OR position('inventory_lock_product' IN pg_get_functiondef(wrapper))=0 OR position('inventory_batch_replace' IN pg_get_functiondef(wrapper))=0 UNION ALL SELECT 'missing_core' FROM f WHERE core IS NULL UNION ALL SELECT 'anonymous_can_create' FROM f WHERE wrapper IS NOT NULL AND has_function_privilege('anon',wrapper,'EXECUTE') UNION ALL SELECT 'authenticated_cannot_create' FROM f WHERE wrapper IS NOT NULL AND NOT has_function_privilege('authenticated',wrapper,'EXECUTE') UNION ALL SELECT 'core_is_exposed' FROM f WHERE core IS NOT NULL AND (has_function_privilege('anon',core,'EXECUTE') OR has_function_privilege('authenticated',core,'EXECUTE'))) SELECT issue FROM checks;
